+#[tokio::test(start_paused = true)]
+async fn remove_last_entry_wakes_poller() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let key1 = queue.insert("foo", ms(100_000));
+    let key2 = queue.insert("bar", ms(100_000));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key1).into_inner(), "foo");
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key2).into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test(start_paused = true)]
+async fn try_remove_last_entry_wakes_poller() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let key1 = queue.insert("foo", ms(100_000));
+    let key2 = queue.insert("bar", ms(100_000));
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.try_remove(&key1).unwrap().into_inner(), "foo");
+    assert!(!queue.is_woken());
+    assert!(queue.try_remove(&key1).is_none());
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.try_remove(&key2).unwrap().into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test(start_paused = true)]
+async fn remove_last_entry_completes_waiting_task() {
+    use std::sync::{Arc, Mutex};
+
+    let mut queue = DelayQueue::new();
+    let key = queue.insert("foo", ms(100_000));
+    let queue = Arc::new(Mutex::new(queue));
+    let polling_queue = queue.clone();
+
+    let poller = tokio::spawn(async move {
+        futures::future::poll_fn(|cx| polling_queue.lock().unwrap().poll_expired(cx)).await
+    });
+
+    sleep(ms(100)).await;
+    queue.lock().unwrap().remove(&key);
+
+    let entry = time::timeout(ms(500), poller)
+        .await
+        .expect("poller was not woken after removing the last entry")
+        .unwrap();
+    assert!(entry.is_none());
+}
+
